css:
:where(.wtyg-map-site_central_banks) *{margin: 0;
            padding: 0;
            box-sizing: border-box;}
:where(.wtyg-map-site_central_banks){--black: #0a0a0a;
            --gold: #d4af37;
            --gold-light: #f4d03f;
            --gold-dark: #b8942c;}
:where(.wtyg-map-site_central_banks){font-family: 'Montserrat', sans-serif;
            background: var(--black);
            color: var(--gold);
            margin: 0;
            padding: 0;}
:where(.wtyg-map-site_central_banks) .map-embed-container{width: 100%;
            height: 700px;
            position: relative;
            background: var(--black);}
:where(.wtyg-map-site_central_banks) h1{font-family: 'Cormorant Garamond', serif;
            font-size: 2.5rem;
            font-weight: 300;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            background: linear-gradient(135deg, var(--gold-light) 0%, var(--gold) 50%, var(--gold-dark) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-align: center;
            padding: 1.5rem 1rem 1rem;
            margin: 0;}
:where(.wtyg-map-site_central_banks) :is([data-wtyg-id="map"],#wtyg-noid-map){width: 100%;
            height: calc(100% - 80px);
            border: 1px solid rgba(212, 175, 55, 0.2);}
:where(.wtyg-map-site_central_banks) .leaflet-popup-content-wrapper{background: rgba(10, 10, 10, 0.95) !important;
            border: 1px solid var(--gold) !important;
            border-radius: 2px !important;
            box-shadow: 0 10px 40px rgba(212, 175, 55, 0.3) !important;
            padding: 0 !important;}
:where(.wtyg-map-site_central_banks) .leaflet-popup-content{margin: 0 !important;
            padding: 1.5rem !important;
            color: var(--gold) !important;
            font-family: 'Montserrat', sans-serif !important;
            min-width: 300px !important;}
:where(.wtyg-map-site_central_banks) .leaflet-popup-tip{background: rgba(10, 10, 10, 0.95) !important;}
:where(.wtyg-map-site_central_banks) .leaflet-popup-close-button{color: var(--gold) !important;}
:where(.wtyg-map-site_central_banks) .popup-content h3{font-family: 'Cormorant Garamond', serif;
            color: var(--gold-light);
            font-size: 1.4rem;
            margin: 0 0 0.5rem 0;
            font-weight: 600;}
:where(.wtyg-map-site_central_banks) .popup-content .country-name{color: var(--gold);
            font-size: 0.85rem;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: 1rem;
            opacity: 0.8;}
:where(.wtyg-map-site_central_banks) .popup-content .detail{color: rgba(212, 175, 55, 0.7);
            font-size: 0.85rem;
            line-height: 1.6;
            margin-bottom: 0.4rem;}
:where(.wtyg-map-site_central_banks) .popup-content .detail strong{color: var(--gold);
            font-weight: 600;}
:where(.wtyg-map-site_central_banks) .leaflet-control-zoom{border: 1px solid var(--gold) !important;
            border-radius: 2px !important;}
:where(.wtyg-map-site_central_banks) .leaflet-control-zoom a{background: rgba(10, 10, 10, 0.9) !important;
            color: var(--gold) !important;
            border: none !important;
            font-size: 20px !important;
            font-weight: 300 !important;}
:where(.wtyg-map-site_central_banks) .leaflet-control-zoom a:hover{background: var(--gold) !important;
            color: var(--black) !important;}
:where(.wtyg-map-site_central_banks) .leaflet-bar{box-shadow: 0 0 20px rgba(212, 175, 55, 0.2) !important;}
@media (max-width: 768px){:where(.wtyg-map-site_central_banks) h1{font-size: 1.8rem;
                padding: 1rem 0.5rem 0.5rem;}
:where(.wtyg-map-site_central_banks) .map-embed-container{height: 500px;}}
